/**
 * Private guards for the ids a write points at: assignees, project leads,
 * labels, parent issues, reply targets and mentions.
 *
 * Every reference must be usable from the organization the change is made in.
 * One that belongs to another organization is refused through
 * `assertOrgScope()`, exactly like any other cross-tenant access; one that is
 * missing, archived, not a current member or otherwise out of place is refused
 * as `NotFoundError`. The guards only read, so a caller that runs them before
 * its first write leaves nothing behind when one throws.
 *
 * Must call (do not reimplement): assertOrgScope, isArchived
 */
import { isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { NotFoundError } from "./_support";
import type { Comment } from "@/types/comment";
import type {
  CommentId,
  IssueId,
  LabelId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { Issue } from "@/types/issue";
import type { Actor, Member } from "@/types/member";

/** A current member: not removed from the organization, and `active`. */
function isCurrentMember(member: Member | null): member is Member {
  return member !== null && member.status === "active";
}

/**
 * Throws `NotFoundError` unless `userId` is a current member of `orgId`.
 * Used for anyone a change hands work to — assignees and project leads.
 */
export async function requireCurrentMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!isCurrentMember(member)) throw new NotFoundError("Member", userId);
  return member;
}

/**
 * Checks that every one of `labelIds` is a label of `orgId`. Another
 * organization's label is a tenant scope violation; an unknown id is not
 * found.
 */
export async function requireOwnLabels(
  actor: Actor,
  orgId: OrgId,
  labelIds: readonly LabelId[],
): Promise<void> {
  if (labelIds.length === 0) return;

  const owners = new Map(
    (await labelRepo.findLabelOwners(labelIds)).map((row) => [
      row.id as string,
      row.orgId,
    ]),
  );

  for (const labelId of labelIds) {
    const owner = owners.get(labelId);
    if (owner === undefined) throw new NotFoundError("Label", labelId);
    assertOrgScope(actor, owner);
    if (owner !== orgId) throw new NotFoundError("Label", labelId);
  }
}

/**
 * Loads the parent of a new sub-issue: a live issue of the same project.
 * Another organization's issue is a tenant scope violation; a missing or
 * archived issue, or one from a different project, is not found.
 */
export async function requireParentIssue(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const parent = await issueRepo.findIssueById(orgId, parentId);
  if (parent === null) {
    await assertOwnerInScope(actor, await issueRepo.findIssueOwner(parentId));
    throw new NotFoundError("Issue", parentId);
  }

  if (isArchived(parent) || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
  return parent;
}

/**
 * Loads the comment a reply answers: a live, top-level comment on the same
 * issue. Another organization's comment is a tenant scope violation; a
 * missing or deleted comment, one on a different issue, or a reply (threads
 * are one level deep) is not found.
 */
export async function requireReplyTarget(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
  parentId: CommentId,
): Promise<Comment> {
  const parent = await commentRepo.findCommentById(orgId, parentId);
  if (parent === null) {
    await assertOwnerInScope(
      actor,
      await commentRepo.findCommentOwner(parentId),
    );
    throw new NotFoundError("Comment", parentId);
  }

  if (
    isArchived(parent) ||
    parent.issueId !== issueId ||
    parent.parentId !== null
  ) {
    throw new NotFoundError("Comment", parentId);
  }
  return parent;
}

/**
 * Narrows `userIds` to the current members of `orgId`, keeping order and
 * dropping duplicates. Anyone else is ignored rather than refused — this is
 * the mention filter, and a stale suggestion must never fail a comment.
 */
export async function keepCurrentMembers(
  orgId: OrgId,
  userIds: readonly UserId[],
): Promise<readonly UserId[]> {
  const kept: UserId[] = [];
  for (const userId of new Set(userIds)) {
    if (isCurrentMember(await memberRepo.findMember(orgId, userId))) {
      kept.push(userId);
    }
  }
  return kept;
}

/** A row that exists in some other organization is a scope violation. */
async function assertOwnerInScope(
  actor: Actor,
  owner: OrgId | null,
): Promise<void> {
  if (owner !== null) assertOrgScope(actor, owner);
}

