import { beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/rate-limit", async () => (await import("$W/tests/server/_support/doubles/misc")).rateLimitModule);
import { subscribe } from "@/lib/event-bus";
import { TenantScopeError } from "@/lib/tenant";
import * as issueService from "@/server/services/issue-service";
import * as commentService from "@/server/services/comment-service";
import * as projectService from "@/server/services/project-service";
import * as memberService from "@/server/services/member-service";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import { getDb, issueLabels } from "@/server/db";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "$W/tests/server/_support/fixtures";

let a: any, b: any, labelA: any, labelB: any, events: string[] = [];
beforeAll(async () => {
  await useTemporaryDatabase();
  a = await createTenant("refa"); b = await createTenant("refb");
  labelA = await labelRepo.insertLabel({ orgId: a.org.id, name: "bug", color: "#000000", description: null });
  labelB = await labelRepo.insertLabel({ orgId: b.org.id, name: "B project secret", color: "#000000", description: null });
  for (const e of ["issue.created","issue.updated","issue.assigned","comment.created","project.created"] as const) subscribe(e, () => { events.push(e); });
});

describe("refs", () => {
  it("labels", async () => {
    events = [];
    const count0 = (await issueService.listIssues(a.actors.owner, { orgId: a.org.id, limit: 50, cursor: null })).total;
    await expect(issueService.createIssue(a.actors.member, { ...issueInput(a.org.id, a.project.id), labelIds: [labelB.id] })).rejects.toBeInstanceOf(TenantScopeError);
    await expect(issueService.createIssue(a.actors.member, { ...issueInput(a.org.id, a.project.id), labelIds: ["01HZZZNONEXISTENTLABEL0000"] })).rejects.toBeInstanceOf(NotFoundError);
    expect((await issueService.listIssues(a.actors.owner, { orgId: a.org.id, limit: 50, cursor: null })).total).toBe(count0);
    expect(events).toEqual([]);
    const ok = await issueService.createIssue(a.actors.member, { ...issueInput(a.org.id, a.project.id), labelIds: [labelA.id, labelA.id] });
    expect(ok.labelIds).toEqual([labelA.id]);
    events = [];
    await expect(issueService.updateIssue(a.actors.owner, { orgId: a.org.id, issueId: ok.id, title: "changed title", labelIds: [labelB.id] })).rejects.toBeInstanceOf(TenantScopeError);
    const after = await issueService.getIssue(a.actors.owner, a.org.id, ok.id);
    expect(after.issue.title).toBe(ok.title);
    expect(after.labels.map((l: any) => l.id)).toEqual([labelA.id]);
    expect(events).toEqual([]);
    getDb().insert(issueLabels).values({ orgId: a.org.id, issueId: ok.id, labelId: labelB.id }).run();
    const stale = await issueService.getIssue(a.actors.owner, a.org.id, ok.id);
    expect(stale.labels.map((l: any) => l.id)).toEqual([labelA.id]);
    expect(stale.issue.labelIds).toEqual([labelA.id]);
  });

  it("parents", async () => {
    const other = await projectRepo.insertProject({ orgId: a.org.id, name: "other", slug: "other", key: "OTH", description: null, visibility: "org", leadId: null, color: "#6366f1", targetDate: null });
    const pA = await issueService.createIssue(a.actors.member, issueInput(a.org.id, a.project.id));
    const pOther = await issueService.createIssue(a.actors.member, issueInput(a.org.id, other.id));
    const pB = await issueService.createIssue(b.actors.member, issueInput(b.org.id, b.project.id));
    const pArch = await issueService.createIssue(a.actors.member, issueInput(a.org.id, a.project.id));
    await issueService.archiveIssue(a.actors.owner, a.org.id, pArch.id);
    events = [];
    await expect(issueService.createIssue(a.actors.member, { ...issueInput(a.org.id, a.project.id), parentId: pB.id })).rejects.toBeInstanceOf(TenantScopeError);
    await expect(issueService.createIssue(a.actors.member, { ...issueInput(a.org.id, a.project.id), parentId: pOther.id })).rejects.toBeInstanceOf(NotFoundError);
    await expect(issueService.createIssue(a.actors.member, { ...issueInput(a.org.id, a.project.id), parentId: pArch.id })).rejects.toBeInstanceOf(NotFoundError);
    await expect(issueService.createIssue(a.actors.member, { ...issueInput(a.org.id, a.project.id), parentId: "01HZZZNONEXISTENTISSUE0000" })).rejects.toBeInstanceOf(NotFoundError);
    expect(events).toEqual([]);
    const child = await issueService.createIssue(a.actors.member, { ...issueInput(a.org.id, a.project.id), parentId: pA.id });
    expect(child.parentId).toBe(pA.id);
  });

  it("assignees and leads", async () => {
    const stranger = await userRepo.insertUser({ email: "stranger@x.test", name: "s", passwordHash: "x" });
    const issue = await issueService.createIssue(a.actors.member, issueInput(a.org.id, a.project.id));
    events = [];
    await expect(issueService.assignIssue(a.actors.owner, { orgId: a.org.id, issueId: issue.id, assigneeId: stranger.id })).rejects.toBeInstanceOf(NotFoundError);
    await expect(issueService.assignIssue(a.actors.owner, { orgId: a.org.id, issueId: issue.id, assigneeId: b.userIds.member })).rejects.toBeInstanceOf(NotFoundError);
    await expect(issueService.createIssue(a.actors.member, issueInput(a.org.id, a.project.id, { assigneeId: stranger.id }))).rejects.toBeInstanceOf(NotFoundError);
    await expect(projectService.createProject(a.actors.owner, { orgId: a.org.id, name: "Strange", slug: "strange", key: "STR", description: null, visibility: "org", leadId: stranger.id, color: "#6366f1", targetDate: null })).rejects.toBeInstanceOf(NotFoundError);
    await expect(projectService.updateProject(a.actors.owner, { orgId: a.org.id, projectId: a.project.id, name: "nope", leadId: stranger.id })).rejects.toBeInstanceOf(NotFoundError);
    expect((await projectRepo.findProjectById(a.org.id, a.project.id))!.name).not.toBe("nope");
    expect(events).toEqual([]);
    const ok = await issueService.assignIssue(a.actors.owner, { orgId: a.org.id, issueId: issue.id, assigneeId: a.userIds.viewer });
    expect(ok.assigneeId).toBe(a.userIds.viewer);
  });

  it("replies and mentions", async () => {
    const i1 = await issueService.createIssue(a.actors.member, issueInput(a.org.id, a.project.id));
    const i2 = await issueService.createIssue(a.actors.member, issueInput(a.org.id, a.project.id));
    const iB = await issueService.createIssue(b.actors.member, issueInput(b.org.id, b.project.id));
    const base = { orgId: a.org.id, issueId: i1.id, body: "hi", parentId: null, mentionedUserIds: [] };
    const top = await commentService.createComment(a.actors.member, base);
    const onOther = await commentService.createComment(a.actors.member, { ...base, issueId: i2.id });
    const reply = await commentService.createComment(a.actors.member, { ...base, parentId: top.id });
    const del = await commentService.createComment(a.actors.member, base);
    await commentService.deleteComment(a.actors.owner, { orgId: a.org.id, commentId: del.id });
    const cB = await commentService.createComment(b.actors.member, { ...base, orgId: b.org.id, issueId: iB.id });
    events = [];
    await expect(commentService.createComment(a.actors.member, { ...base, parentId: onOther.id })).rejects.toBeInstanceOf(NotFoundError);
    await expect(commentService.createComment(a.actors.member, { ...base, parentId: reply.id })).rejects.toBeInstanceOf(NotFoundError);
    await expect(commentService.createComment(a.actors.member, { ...base, parentId: del.id })).rejects.toBeInstanceOf(NotFoundError);
    await expect(commentService.createComment(a.actors.member, { ...base, parentId: cB.id })).rejects.toBeInstanceOf(TenantScopeError);
    expect(events).toEqual([]);

    const viewerMember = await memberRepo.findMember(a.org.id, a.userIds.viewer);
    await memberService.removeMember(a.actors.owner, { orgId: a.org.id, memberId: viewerMember!.id });
    const c = await commentService.createComment(a.actors.member, { ...base, body: "cc @viewer @admin @owner", mentionedUserIds: [a.userIds.viewer, b.userIds.admin, a.userIds.admin] });
    expect([...c.mentionedUserIds].sort()).toEqual([a.userIds.admin, a.userIds.owner].sort());
    const notes = await notificationRepo.listNotifications({ orgId: a.org.id, recipientId: a.userIds.viewer, limit: 50, cursor: null } as any);
    expect(notes.items.filter((n: any) => n.kind === "comment_mention")).toEqual([]);
  });
});
EOF
